window.kbPageData["views/entry/k-500c1a1127469d33"] = {"key":"entry/k-500c1a1127469d33","state":{"route":"entry/k-500c1a1127469d33"},"node":{"id":"k-500c1a1127469d33","mode":"k","title":"安全生产行政处罚中的生产经营单位","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["安全生产行政处罚中生产经营单位的主体范围"],"qs":["江苏 2023 B类 行测#18"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"已核实规章版本、发布机关和主体范围。所查类似案材料为案例评析，尚需核对生效裁判对出租方主体身份及连带责任的认定。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：沈某将违建厂房出租给孙某","review":{"definition":"原题引文：沈某将违建厂房出租给孙某","explanation":"沈某有偿出租违建厂房供孙某加工，并约定被举报时退房退租，应结合这些实际经营事实判断其主体身份。《人民法院报》对类似案情的评析主张，明知厂房用于生产经营而有偿出租的自然人可纳入安全生产法上的生产经营单位。该评析使B项的排除性判断缺乏依据，也提示当时《安全生产法》第一百条的连带责任可能适用，仍须查明出租行为与事故损害的法律因果关系。","references":[{"source":"web-0f83148a566a7429","location":"公布说明、第二条、第六十八条","quote":"本办法所称的生产经营单位"},{"source":"web-ca82f6983865dad4","location":"评析第二点","quote":"安全生产法的适用对象“生产经营单位”应包含自然人"},{"source":"web-09971d56c6984e1f","location":"第一百条第一款","quote":"与承包方、承租方承担连带赔偿责任"}],"evidence":"沈某将违建厂房出租给孙某","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#18":{"paper":"江苏 2023 B类 行测","n":18,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",7],"card":"46c0d47c902fde44cdbb48f7","links":[{"id":"k-500c1a1127469d33","role":"解题依据","why":"从事生产经营活动的自然人可以纳入该主体范围，判断时须结合其实际活动。"}]}},"terms":{},"references":{"web-0f83148a566a7429":{"name":"《安全生产违法行为行政处罚办法》（2015年修正）","url":"https://www.mem.gov.cn/gk/gwgg/agwzlfl/zjl_01/201504/t20150402_233760.shtml"},"web-ca82f6983865dad4":{"name":"《人民法院报》案例评析《出租厂房的自然人应认定为“生产经营单位”》","url":"https://www.sdcourt.gov.cn/qdtlfy/368549/368550/7367955/index.html"},"web-09971d56c6984e1f":{"name":"《中华人民共和国安全生产法》（2014年修正）","url":"https://www.miit.gov.cn/jgsj/aqs/zcfgbz/art/2020/art_12452e1fba764bd3aa852a0b08306713.html"}},"topics":[],"units":{"k-500c1a1127469d33":[["江苏 2023 B类 行测#18"]]}};
